/**
 * Texture bake cache.
 *
 * Every texture in this game is generated by code (seeded, so it is identical every time). Generating them costs CPU
 * on every launch, which is what makes a phone warm up and the first seconds stutter. This stores each finished
 * texture in the device's IndexedDB the first time it is built, and on every later launch reads the saved pixels back
 * instead of drawing them again.
 *
 * - bakedData(key, build)           for generators that return typed arrays (ground detail, paving, paint, concrete)
 * - bakedCanvas(key, w, h, paint)   for canvas drawn textures (asphalt, gravel, decals)
 * - loadBaked()                     reads everything saved into memory (call once before the textures are requested)
 * - flushBaked()                    waits until all new textures are safely written
 *
 * Bump BAKE_VERSION whenever a generator's look changes, so old saved pixels are thrown away and rebuilt.
 * If IndexedDB is unavailable (private mode, blocked) everything still works: textures are simply generated each launch.
 */

export const BAKE_VERSION = 'v2-realism';

const DB_NAME = 'bl-texture-bake';
const STORE = 'tex';
const prefix = `${BAKE_VERSION}|`;

const mem = new Map<string, unknown>();
const pending: Promise<void>[] = [];
let dbPromise: Promise<IDBDatabase | null> | null = null;
let stats = { restored: 0, built: 0, savedBytes: 0 };

interface PixelStore {
  w: number;
  h: number;
  data: Uint8ClampedArray;
  /** texture settings (wrap / anisotropy / colour space ...) for textures whose generator is skipped on restore; null for a plain canvas */
  opts?: Record<string, unknown> | null;
}

function openDb(): Promise<IDBDatabase | null> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve) => {
    try {
      if (typeof indexedDB === 'undefined') return resolve(null);
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(STORE)) req.result.createObjectStore(STORE);
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
      req.onblocked = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
  return dbPromise;
}

function sizeOf(v: unknown): number {
  if (ArrayBuffer.isView(v)) return v.byteLength;
  if (v && typeof v === 'object') return Object.values(v as Record<string, unknown>).reduce<number>((a, x) => a + sizeOf(x), 0);
  return 0;
}

function save(key: string, value: unknown): void {
  pending.push(
    openDb().then(
      (db) =>
        new Promise<void>((resolve) => {
          if (!db) return resolve();
          try {
            const tx = db.transaction(STORE, 'readwrite');
            tx.objectStore(STORE).put(value, key);
            tx.oncomplete = () => {
              stats.savedBytes += sizeOf(value);
              resolve();
            };
            tx.onerror = tx.onabort = () => resolve(); // quota / blocked: not fatal, it will just be rebuilt next time
          } catch {
            resolve();
          }
        }),
    ),
  );
}

/** Ask the browser not to evict our saved files when the phone is low on space (best effort, ignored where unsupported). */
export function requestPersistentStorage(): void {
  try {
    void navigator.storage?.persist?.();
  } catch {
    /* ignore */
  }
}

/** Reads every saved texture of the current version into memory. Resolves with how many were found. Old versions are deleted. */
export async function loadBaked(): Promise<number> {
  const db = await openDb();
  if (!db) return 0;
  return new Promise<number>((resolve) => {
    try {
      const tx = db.transaction(STORE, 'readwrite');
      const store = tx.objectStore(STORE);
      const cur = store.openCursor();
      let n = 0;
      cur.onsuccess = () => {
        const c = cur.result;
        if (!c) return;
        if (typeof c.key === 'string' && c.key.startsWith(prefix)) {
          mem.set(c.key, c.value);
          n++;
        } else {
          c.delete(); // saved by an older BAKE_VERSION
        }
        c.continue();
      };
      tx.oncomplete = () => resolve(n);
      tx.onerror = tx.onabort = () => resolve(n);
    } catch {
      resolve(0);
    }
  });
}

export function bakedData<T>(key: string, build: () => T, keep = true): T {
  const k = prefix + key;
  if (mem.has(k)) {
    stats.restored++;
    const hit = mem.get(k) as T;
    if (!keep) mem.delete(k);
    return hit;
  }
  const v = build();
  stats.built++;
  if (keep) mem.set(k, v);
  save(k, v);
  return v;
}

export function bakedCanvas(key: string, w: number, h: number, paint: (ctx: CanvasRenderingContext2D) => void): HTMLCanvasElement {
  const k = prefix + key;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;
  const hit = mem.get(k) as PixelStore | undefined;
  if (hit && hit.w === w && hit.h === h && hit.data.length === w * h * 4) {
    ctx.putImageData(new ImageData(hit.data, w, h), 0, 0);
    mem.delete(k); // the canvas owns the pixels now: free the copy
    stats.restored++;
    return canvas;
  }
  paint(ctx);
  stats.built++;
  save(k, { w, h, data: ctx.getImageData(0, 0, w, h).data } satisfies PixelStore);
  return canvas;
}

/**
 * For code that paints its own canvases (the barracks): hands back the pixels saved for `key`, or undefined when this
 * texture is not on the device yet. The copy in memory is released (the caller owns the pixels now).
 */
export function takeBakedPixels(key: string): PixelStore | undefined {
  const k = prefix + key;
  const hit = mem.get(k) as PixelStore | undefined;
  if (!hit || !hit.data || hit.data.length !== hit.w * hit.h * 4) return undefined;
  mem.delete(k);
  stats.restored++;
  return hit;
}

/** Saves a freshly painted canvas (plus its texture settings) to the device under `key`. */
export function saveBakedPixels(key: string, canvas: HTMLCanvasElement, opts: Record<string, unknown> | null): void {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  stats.built++;
  save(prefix + key, { w: canvas.width, h: canvas.height, data: ctx.getImageData(0, 0, canvas.width, canvas.height).data, opts } satisfies PixelStore);
}

/** How many saved textures (still unused, in memory) have a key starting with `start`. */
export function countBaked(start: string): number {
  const p = prefix + start;
  let n = 0;
  for (const k of mem.keys()) if (k.startsWith(p)) n++;
  return n;
}

/** Waits for every texture built this session to be written to the device. */
export async function flushBaked(): Promise<void> {
  while (pending.length) await pending.shift();
}

export function bakeStats(): { restored: number; built: number; savedBytes: number } {
  return { ...stats };
}
